<?php
declare(strict_types=1);use Vendi\Database\Connection;use Vendi\Http\ApiGuard;use Vendi\Branches\BranchContextService;use Vendi\Branches\BranchClock;use Vendi\Reports\ReportService;
require dirname(__DIR__,3).'/vendor/autoload.php';session_start();header('Content-Type: application/json; charset=utf-8');
try{$u=ApiGuard::session();$db=Connection::make(['host'=>getenv('DB_HOST')?:'127.0.0.1','port'=>(int)(getenv('DB_PORT')?:3306),'database'=>getenv('DB_DATABASE')?:'vendi','username'=>getenv('DB_USERNAME')?:'root','password'=>getenv('DB_PASSWORD')?:'']);ApiGuard::permission($db,$u,'reports.view');$branch=(int)($_GET['branch_id']??0);if(!$branch)$branch=(new BranchContextService($db))->active($u);ApiGuard::branch($db,$u,$branch);$clock=new BranchClock($db);$today=$clock->now((int)$u['business_id'],$branch)->format('Y-m-d');$from=(string)($_GET['from']??$today);$to=(string)($_GET['to']??$today);if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from.$to) && (!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)))throw new RuntimeException('Fechas inválidas.');if($from>$to)[$from,$to]=[$to,$from];echo json_encode(['ok'=>true,'branch_id'=>$branch,'from'=>$from,'to'=>$to]+(new ReportService($db))->sales((int)$u['business_id'],$branch,$from,$to),JSON_UNESCAPED_UNICODE);}catch(Throwable$e){http_response_code(in_array((int)$e->getCode(),[401,403],true)?(int)$e->getCode():422);echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}